def dfs_visit(graph, start):
    visited = []
    stack = [start]
    seen = {start}

    while stack:
        node = stack.pop()
        visited.append(node)

        # Reverse neighbors to maintain traditional DFS order (left-to-right)
        # since a stack is Last-In-First-Out (LIFO)
        for neighbor in reversed(graph.get(node, [])):
            if neighbor not in seen:
                seen.add(neighbor)
                stack.append(neighbor)

    return visited
```

